function syncOnlineTransportUi() {
  if (!byId('onlineUiRoot')) return;
  byId('onlineUiRoot').hidden = !onlineTransportSelected;
  if (onlineNativeTransport) for (const child of lanPanel.children) {
    if (child.id === 'onlineUiRoot' || child.id === 'lanStatus') continue;
    child.hidden = onlineTransportSelected;
  }
  const activeMenu = onlineTransportSelected && royalOnlineMode() && !document.body.classList.contains('title-active');
  if (!activeMenu && matchmakingSocket && !matchmakingLocked()) stopMatchmaking();
}

function stopBackgroundMatchmaking() {
  if (onlineSession?.presence) return;
  if (onlineMatchFlowBlocksPlay()) { failOnlineMatchFlow('opponent_left'); return; }
  if (!matchmakingSocket) return;
  const wasSearching = matchmakingRequested || matchmakingState === 'waiting' || matchmakingLocked();
  if (matchmakingLocked() && !lanConnected) closeLanConnection(false);
  stopMatchmaking();
  if (wasSearching && onlineTransportSelected && !lanConnected) setLanStatus('Search stopped while the app was in the background.');
}
document.addEventListener('visibilitychange', () => { if (document.hidden) stopBackgroundMatchmaking(); });
document.addEventListener('kingpong-background', () => { if (window.KingPongBackgrounded) stopBackgroundMatchmaking(); });

// Optional online wire format 1. JSON tuples remove field names, not state.
// Every snapshot is independently decodable: no delta baseline, quantized physics,
// indexed paddle IDs, or dependency on delivery order across the two channels.
const ONLINE_WIRE_VERSION = 1;
const ONLINE_WIRE_FIELDS = Object.freeze({
  selection: ['arena', 'left', 'right'], rules: ['id', 'revision'],
  ball: ['x', 'y', 'vx', 'vy', 'lastScored', 'rallyLaunchFramesRemaining',
    'rallyLaunchTargetSpeed', 'rallySpawnPulseX', 'rallySpawnPulseY'],
  split: ['x', 'y', 'vx', 'vy', 'rush'], pickup: ['type', 'x', 'y', 'ttl'],
  hit: ['seq', 'y', 'ttl'], pulse: ['x', 'y', 'remaining'], cue: ['seq', 'kind', 'type', 'age'],
  hazard: ['id', 'x', 'y', 'hitFlash']
});

function encodeOnlineWire(m) {
  const pack = (kind, value) => value === null ? null : ONLINE_WIRE_FIELDS[kind].map(k => value[k]);
  const head = ['kp', ONLINE_WIRE_VERSION, m.type === 'input' ? 'i' : 's', m.room, m.seq];
  if (m.type === 'input') {
    const input = onlineRematchReady ? [...head, m.axis, m.targetY, m.round] : [...head, m.axis, m.targetY];
    if (m.presenceEpoch !== undefined) input.push(m.presenceEpoch);
    return input;
  }
  if (m.type !== 'state') return m;
  const r = m.royal;
  const state = [...head, m.tick, m.inputSeq, pack('selection', m.selection), pack('rules', m.rules),
    [m.activeCampaign, m.levelIndex, m.leftY, m.rightY, m.leftScore, m.rightScore], pack('ball', m.ball),
    [m.paused, m.waitingForServe, m.gameOver, m.levelCleared, m.campaignCleared], m.resumeCountdownMs,
    [r.rally, r.rush, pack('split', r.split), pack('pickup', r.pickup), [r.guards.left, r.guards.right],
      [pack('hit', r.guardHits.left), pack('hit', r.guardHits.right)], pack('pulse', r.powerupPulse),
      r.cueSeq, r.cues.map(c => pack('cue', c))],
    m.hazards.map(h => pack('hazard', h)), m.endMessage];
  // Keep legacy v1 tuples unchanged unless the peer acknowledged this extension.
  if (onlinePointServeReady || onlineRematchReady) state.push(m.pointServeMs ?? 0);
  if (onlineRematchReady) state.push(m.round);
  if (m.presenceEpoch !== undefined) state.push(m.presenceEpoch);
  return state;
}

function decodeOnlineWire(a) {
  const tuple = (v, n) => Array.isArray(v) && v.length === n;
  if (!Array.isArray(a) || a[0] !== 'kp' || a[1] !== ONLINE_WIRE_VERSION) return null;
  const m = {v: LAN_SIGNAL_VERSION, gameplay: 'royal', matchRules: 'presets', room: a[3], seq: a[4]};
  if (a[2] === 'i' && tuple(a, 7)) return {...m, type: 'input', axis: a[5], targetY: a[6]};
  if (a[2] === 'i' && onlineRematchReady && tuple(a, 8)) return {...m, type: 'input', axis: a[5], targetY: a[6], round: a[7]};
  const presence = typeof multiplayerPresence === 'function' && multiplayerPresence();
  if (a[2] === 'i' && presence && tuple(a, 9)) return {...m, type: 'input', axis: a[5], targetY: a[6], round: a[7], presenceEpoch: a[8]};
  if (a.length >= 18 && !onlineRematchReady || a.length === 19 && !presence) return null;
  if (a[2] !== 's' || !(tuple(a, 16) || tuple(a, 17) || tuple(a, 18) || tuple(a, 19)) || !tuple(a[9], 6) || !tuple(a[11], 5) ||
      !tuple(a[13], 9) || !tuple(a[13][4], 2) || !tuple(a[13][5], 2) ||
      !Array.isArray(a[13][8]) || a[13][8].length > 16 || !Array.isArray(a[14]) || a[14].length > 128) return null;
  // Shape errors are rejected here; the existing gameplay validators then enforce
  // types, ranges, rules, arena consistency, sequence order and host authority.
  let valid = true;
  const unpack = (kind, value, nullable = false) => {
    if (nullable && value === null) return null;
    const fields = ONLINE_WIRE_FIELDS[kind];
    if (!tuple(value, fields.length)) { valid = false; return null; }
    return Object.fromEntries(fields.map((k, i) => [k, value[i]]));
  };
  const p = a[9], flags = a[11], r = a[13];
  Object.assign(m, {type: 'state', tick: a[5], inputSeq: a[6], selection: unpack('selection', a[7]),
    rules: unpack('rules', a[8]), activeCampaign: p[0], levelIndex: p[1], leftY: p[2], rightY: p[3],
    leftScore: p[4], rightScore: p[5], ball: unpack('ball', a[10]), paused: flags[0],
    waitingForServe: flags[1], gameOver: flags[2], levelCleared: flags[3], campaignCleared: flags[4],
    resumeCountdownMs: a[12], royal: {rally: r[0], rush: r[1], split: unpack('split', r[2], true),
      pickup: unpack('pickup', r[3], true), guards: {left: r[4][0], right: r[4][1]},
      guardHits: {left: unpack('hit', r[5][0], true), right: unpack('hit', r[5][1], true)},
      powerupPulse: unpack('pulse', r[6], true), cueSeq: r[7], cues: r[8].map(c => unpack('cue', c))},
    hazards: a[14].map(h => unpack('hazard', h)), endMessage: a[15]});
  if (a.length >= 17) m.pointServeMs = a[16];
  if (a.length >= 18) m.round = a[17];
  if (a.length === 19) m.presenceEpoch = a[18];
  return valid ? m : null;
}

let onlineWireReady = false;
let onlineRematchReady = false;
let onlineIntentReady = false;
let onlinePointServeReady = false;
let onlineWireAttempts = 0;
let onlineWireHelloAt = -Infinity;
let onlineLastInput = null;
let onlineInputAck = -1;

function resetOnlineWire() {
  onlineRematchReady = false;
  onlineWireReady = false;
  onlineIntentReady = false;
  onlinePointServeReady = false;
  onlineWireAttempts = 0;
  onlineWireHelloAt = -Infinity;
  onlineLastInput = null;
  onlineInputAck = -1;
}

function sendOnlineWireHello(ack = false) {
  return onlineLanSend({v: LAN_SIGNAL_VERSION, type: 'net-format', room: lanRoomCode,
    format: ONLINE_WIRE_VERSION, ack, inputIntent: 1, pointServe: 1,
    presence: 1, rematch: 1, rematchToken: multiplayerRematch()?.token});
}

function negotiateOnlineWire() {
  // A peer may open its channels a little later. Retry without adding timers.
  // Older clients ignore the extension and continue using validated legacy JSON.
  if (onlineWireReady || onlineWireAttempts >= 4 || performance.now() - onlineWireHelloAt < 500) return;
  if (sendOnlineWireHello()) { onlineWireAttempts++; onlineWireHelloAt = performance.now(); }
}

function receiveOnlineWireHello(m) {
  if (!onlineSession || !lanRoomCode || m.v !== LAN_SIGNAL_VERSION || m.room !== lanRoomCode ||
      m.gameplay !== 'royal' || m.matchRules !== 'presets' || m.format !== ONLINE_WIRE_VERSION ||
      typeof m.ack !== 'boolean') return;
  receiveRematchHello(m);
  if (typeof receivePresenceHello === 'function') receivePresenceHello(m);
  if (m.ack) { onlineWireReady = true; onlineIntentReady = m.inputIntent === 1; onlinePointServeReady = m.pointServe === 1; }
  else sendOnlineWireHello(true);
}

// Online-only adapters retain the existing browser reconciliation and reliable control channel.
function onlineLanSend(payload) {
  payload.gameplay = "royal";
  /* ROYAL POLISH */
  payload.matchRules = "presets";
  /* END ROYAL POLISH */
  if (payload.type !== 'net-format') negotiateOnlineWire();
  if (onlineRematchReady && ['state', 'input', 'action'].includes(payload.type)) payload.round = multiplayerRematch().round;
  const presence = typeof multiplayerPresence === 'function' && multiplayerPresence();
  if (presence && ['state', 'input', 'action', 'match-setup'].includes(payload.type)) payload.presenceEpoch = presence.epoch;
  if (presence?.suspended && ['state', 'input', 'action', 'match-setup', 'rematch'].includes(payload.type) &&
      !presence.sendingSnapshot && !(payload.type === 'rematch' && payload.kind === 'leave')) return false;
  if (presence?.sendingSnapshot && payload.type === 'state') payload.presenceSnapshot = true;
  const channel = (payload.presenceSnapshot || payload.type === 'presence' || payload.type === "rematch" || payload.type === "action" || payload.type === "selection" || payload.type === "rules" || payload.type === "match-setup" || payload.type === "net-format") ?
    onlineControlChannel : lanChannel;
  if (!channel || channel.readyState !== "open") return false;
  try {
    if (channel.bufferedAmount > 65536) return false;
    channel.send(JSON.stringify(onlineWireReady && !payload.presenceSnapshot && ['state', 'input'].includes(payload.type) ? encodeOnlineWire(payload) : payload));
    if (presence) presence.lastSent = Date.now();
    return true;
  } catch {
    if (onlineSession) onlineSession.fail("connection_lost");
    return false;
  }
}

function onlineSendLanInput(gamepads = null, force = false) {
  if (lanRole !== "guest" || !lanChannel || lanChannel.readyState !== "open") return;
  const localInput = readLocalLanInput(gamepads);
  const now = performance.now();
  // Match snapshot precision (0.01 px), well below a rendered pixel. Keep the
  // prediction history at its original precision for existing reconciliation.
  // Upgraded peers send a destination/axis intent. Older peers keep position reconciliation.
  const targetY = onlineIntentReady ? localInput.targetY : onlineHasState && !paused ? Math.round(right.y * 100) / 100 : localInput.targetY;
  const changed = !onlineLastInput || localInput.axis !== onlineLastInput.axis || targetY !== onlineLastInput.targetY;
  // Keep the legacy packet cadence when the peer cannot negotiate compact input.
  const urgent = !onlineLastInput || localInput.axis !== onlineLastInput.axis || onlineWireReady && changed;
  const acknowledged = onlineLastInput && onlineInputAck >= onlineLastInput.proofSeq;
  // Changes are sent on this physics tick. Unacknowledged releases/targets keep
  // retrying at the original 30 Hz; only confirmed idle input uses a 250 ms lease.
  const idle = !changed && localInput.axis === 0 && acknowledged;
  if (!force && !urgent && (idle ? now - onlineLastInput.at < 250 : frame % 2 !== 0)) return;
  const seq = ++lanInputSeq;
  onlineInput(localInput, seq);
  if (lanSend({v: LAN_SIGNAL_VERSION, type: "input", room: lanRoomCode, seq,
      axis: localInput.axis, targetY})) {
    onlineLastSentAxis = localInput.axis;
    onlineLastInput = {axis: localInput.axis, targetY, seq, at: now,
      proofSeq: changed ? seq : onlineLastInput.proofSeq};
  } else onlineInputs.delete(seq);

}

function onlineApplyLanHostState(state) {
  if (Number.isSafeInteger(state.inputSeq)) onlineInputAck = Math.max(onlineInputAck, state.inputSeq);
  const previousArena = matchArenaId;
  applySelectionState(state.selection);
  const campaignIndex = clamp(Math.round(Number(state.activeCampaign) || 0), 0, CAMPAIGNS.length - 1);
  const levelInCampaign = clamp(Math.round(Number(state.levelIndex) || 0), 0, CAMPAIGNS[campaignIndex].levels.length -
    1);
  const levelChanged = previousArena !== matchArenaId || mode !== 2 || activeCampaign !== campaignIndex ||
    levelIndex !== levelInCampaign;
  mode = 2;
  if (levelChanged) {
    activeCampaign = campaignIndex;
    levelIndex = levelInCampaign;
    cloneHazards();
    setAccent();
    populateCustomLevelSelect();
    syncCustomLevelSelectToCurrent();
  }
  left.y = clamp(finiteNumber(state.leftY, left.y), visiblePlayfieldBounds().top, visiblePlayfieldBounds().bottom -
    PADDLE_H);
  right.y = clamp(onlinePaddleState(state, levelChanged), visiblePlayfieldBounds().top, visiblePlayfieldBounds()
    .bottom - PADDLE_H);
  left.score = clamp(Math.round(Number(state.leftScore) || 0), 0, MATCH_SCORE_MAX);
  right.score = clamp(Math.round(Number(state.rightScore) || 0), 0, MATCH_SCORE_MAX);
  if (state.ball && typeof state.ball === "object") {
    ball.prevX = ball.x;
    ball.prevY = ball.y;
    ball.x = clamp(finiteNumber(state.ball.x, ball.x), -BALL_SIZE * 2, W + BALL_SIZE * 2);
    ball.y = clamp(finiteNumber(state.ball.y, ball.y), visiblePlayfieldBounds().top, visiblePlayfieldBounds().bottom -
      BALL_SIZE);
    ball.vx = clamp(Number(state.ball.vx) || 0, -20, 20);
    ball.vy = clamp(Number(state.ball.vy) || 0, -20, 20);
    ball.lastScored = clamp(Math.round(Number(state.ball.lastScored) || 0), -1, 1);
    rallyLaunchFramesRemaining = clamp(Math.round(Number(state.ball.rallyLaunchFramesRemaining) || 0), 0,
      RALLY_LAUNCH_RAMP_FRAMES);
    rallyLaunchTargetSpeed = clamp(Number(state.ball.rallyLaunchTargetSpeed) || 0, 0, 20);
    rallySpawnPulseX = clamp(finiteNumber(state.ball.rallySpawnPulseX, ball.x + BALL_HALF), 0, W);
    rallySpawnPulseY = clamp(finiteNumber(state.ball.rallySpawnPulseY, ball.y + BALL_HALF), 0, H);
  }
  if (Array.isArray(state.hazards)) {
    state.hazards.slice(0, 128).forEach(source => {
      if (!source || typeof source !== "object") return;
      const hazard = hazards.find(item => item.id === source.id);
      if (!hazard) return;
      if (Number.isFinite(Number(source.x))) hazard.x = clamp(Number(source.x), -W, W * 2);
      if (Number.isFinite(Number(source.y))) hazard.y = clamp(Number(source.y), -H, H * 2);
      hazard.hitFlash = clamp(Math.round(Number(source.hitFlash) || 0), 0, 20);
    });
  }
  paused = Boolean(state.paused);
  const syncedResumeCountdownMs = clamp(Number(state.resumeCountdownMs) || 0, 0, RESUME_COUNTDOWN_MS);
  resumeCountdownEndAt = paused && syncedResumeCountdownMs > 0 ? performance.now() + syncedResumeCountdownMs : 0;
  waitingForServe = Boolean(state.waitingForServe);
  gameOver = Boolean(state.gameOver);
  levelCleared = Boolean(state.levelCleared);
  campaignCleared = Boolean(state.campaignCleared);
  endMessage = String(state.endMessage || "").slice(0, 180);
  applyPointServeSnapshot(state);
  if (document.body.classList.contains("title-active")) hideTitleScreen();
  if (levelChanged) {
    updateModeControls();
    updateHud();
  }
  applyRoyalState(state.royal);
  queueGuestSnapshot(state);
}

function onlineUpdatePlayerPaddles(gamepads = getConnectedGamepads()) {
  const bounds = visiblePlayfieldBounds();
  if (isLanGuestActive()) {
    const input = readLocalLanInput(gamepads);
    if (input.targetY !== null) {
      right.y = input.targetY;
    } else {
      right.y += input.axis * PADDLE_SPEED;
    }
    clampPaddleToVisiblePlayfield(left);
    clampPaddleToVisiblePlayfield(right);
    return;
  }
  const lanLocalPaddleControls = mode === 2 && (isLanHostActive() || lanRole === "host");
  const singlePlayerControls = mode !== 2 || lanLocalPaddleControls;
  const leftUp = keys.has("w") || keys.has("W") || singlePlayerControls && keys.has("ArrowUp");
  const leftDown = keys.has("s") || keys.has("S") || singlePlayerControls && keys.has("ArrowDown");
  if (leftUp) {
    left.y -= PADDLE_SPEED;
  }
  if (leftDown) {
    left.y += PADDLE_SPEED;
  }
  if (touchPaddleTargets.left !== null) {
    left.y = touchPaddleTargets.left;
  }
  if (mode === 2 && !isLanHostActive() && touchPaddleTargets.right !== null) {
    right.y = touchPaddleTargets.right;
  }
  const primaryPad = gamepads[0];
  const secondaryPad = gamepads[1];
  if (singlePlayerControls && primaryPad) {
    left.y += gamepadVertical(primaryPad, 1) * PADDLE_SPEED;
  }
  if (mode === 2) {
    if (isLanHostActive()) {
      onlineAppliedInputSeq = lanLastInputSeq;
      const remoteFresh = performance.now() - lanRemoteInput.lastAt < 1200;
      if (remoteFresh && lanRemoteInput.targetY !== null) {
        right.y = clamp(lanRemoteInput.targetY, bounds.top, bounds.bottom - PADDLE_H);
      } else if (remoteFresh) {
        right.y += lanRemoteInput.axis * PADDLE_SPEED;
      }
    } else {
      if (keys.has("ArrowUp")) {
        right.y -= PADDLE_SPEED;
      }
      if (keys.has("ArrowDown")) {
        right.y += PADDLE_SPEED;
      }
      if (primaryPad) {
        left.y += gamepadVertical(primaryPad, 1) * PADDLE_SPEED;
      }
      if (secondaryPad) {
        right.y += gamepadVertical(secondaryPad, 1) * PADDLE_SPEED;
      }
    }
  }
  clampPaddleToVisiblePlayfield(left);
  clampPaddleToVisiblePlayfield(right);
}

function onlineSendLanState(force = false) {
  if (!isLanHostActive()) return;
  if (!force && frame % LAN_STATE_EVERY_FRAMES !== 0) return;
  /* ROYAL POLISH */
  sendMatchRules();
  /* END ROYAL POLISH */
  lanSend({
    v: LAN_SIGNAL_VERSION,
    type: "state",
    room: lanRoomCode,
    seq: ++lanStateSeq,
    // Paused snapshots acknowledge receipt; reconciliation already clears prediction while paused.
    inputSeq: paused ? lanLastInputSeq : onlineAppliedInputSeq,
    tick: frame,
    selection: selectionPayload(),
    royal: packRoyalState(),
    /* ROYAL POLISH */
    rules: matchRulePayload(false),
    /* END ROYAL POLISH */
    activeCampaign,
    levelIndex,
    leftY: Math.round(left.y * 100) / 100,
    rightY: Math.round(right.y * 100) / 100,
    leftScore: left.score,
    rightScore: right.score,
    ball: {
      x: Math.round(ball.x * 100) / 100,
      y: Math.round(ball.y * 100) / 100,
      vx: Math.round(ball.vx * 100) / 100,
      vy: Math.round(ball.vy * 100) / 100,
      lastScored: ball.lastScored,
      rallyLaunchFramesRemaining,
      rallyLaunchTargetSpeed,
      rallySpawnPulseX,
      rallySpawnPulseY
    },
    hazards: serializeLanHazards(),
    paused,
    resumeCountdownMs: Math.round(resumeCountdownRemainingMs()),
    pointServeMs: pointServeSnapshotMs(),
    waitingForServe,
    gameOver,
    levelCleared,
    campaignCleared,
    endMessage: String(endMessage || "").slice(0, 180)
  });
}

// Online matches share reliable ready/countdown and configuration acknowledgement.
// Public matches resolve preferences after matching, without changing the queue.
let onlineMatchFlow = null;

function onlineMatchFlowVisible() {
  return Boolean(onlineMatchFlow && onlineMatchFlow.phase !== 'playing');
}

function onlineMatchFlowBlocksPlay() {
  return onlineMatchFlowVisible() && onlineMatchFlow.phase !== 'go';
}

function resetOnlineMatchFlow() {
  onlineMatchFlow = null;
  resumeCountdownEndAt = 0;
  lastResumeCountdownNumber = 0;
  syncOnlineMatchFlowUi();
}

function beginOnlineMatchFlow() {
  onlineMatchFlow = {id: onlineMatchAssignment?.id || 'private:' + lanRoomCode,
    localPowerups: onlineMatchAssignment ? (matchmakingPowerupsPreference ?? playerPreference('royalPowerupsEnabled')) : null,
    peerPowerups: null, agreedPowerups: null,
    privateRoom: !onlineMatchAssignment, configured: false, peerInitialized: false, phase: 'connecting', localReady: false,
    hostReady: false, guestReady: false, peerHello: false, sequence: 0, remoteSequence: -1,
    localPaddle: matchPaddles[lanRole === 'guest' ? 'right' : 'left'], lastHelloAt: -Infinity};
  onlineGameBlocked = paused = true;
  waitingForServe = true;
  clearHeldInput();
  setMenusVisible(false);
  syncRoyalUi(true);
}

function sendOnlineMatchSetup(kind, fields = {}) {
  if (!onlineMatchFlow || !lanConnected) return false;
  return lanSend({v: LAN_SIGNAL_VERSION, room: lanRoomCode, type: 'match-setup', protocol: 1,
    match: onlineMatchFlow.id, kind, ...fields});
}

function sendOnlineMatchStatus() {
  if (lanRole !== 'host' || !onlineMatchFlow) return;
  sendOnlineMatchSetup('status', {phase: onlineMatchFlow.phase, hostReady: onlineMatchFlow.hostReady,
    guestReady: onlineMatchFlow.guestReady, seq: ++onlineMatchFlow.sequence,
    remainingMs: Math.round(resumeCountdownRemainingMs())});
}

function onlineMatchTransportReady() {
  const flow = onlineMatchFlow;
  if (!flow || flow.phase !== 'connecting') return;
  flow.phase = 'connected';
  flow.connectedUntil = performance.now() + 600;
  flow.handshakeDeadline = performance.now() + 8000;
  onlineGameBlocked = paused = true;
  sendOnlineMatchHello();
  syncRoyalUi(true);
}

function sendOnlineMatchHello() {
  const flow = onlineMatchFlow;
  flow.lastHelloAt = performance.now();
  // The first host snapshot may precede the guest's channel-open callback.
  // Re-send the locally selected paddle before hello, in reliable channel order.
  if (lanRole === 'guest') lanSend({v: LAN_SIGNAL_VERSION, room: lanRoomCode, type: 'selection',
    seq: ++selectionSequence, paddle: flow.localPaddle});
  sendOnlineMatchSetup('hello', flow.privateRoom ? {} : {powerupAgreement: 1, powerupsPreference: flow.localPowerups});
  if (lanRole === 'host') sendPrivateMatchConfiguration();
  if (lanRole === 'guest' && flow.configured && onlineHasState) {
    sendOnlineMatchSetup('initialized', {configuration: flow.configuration});
  }
}

function confirmOnlineMatchReady() {
  const flow = onlineMatchFlow;
  if (!flow || flow.phase !== 'ready' || !lanConnected || flow.localReady && !flow.privateRoom) return;
  flow.localReady = !flow.localReady;
  // The Ready click is a user gesture. Unlock SFX here so the later remote
  // countdown/GO and scoring cues can play even if music was switched off.
  if (flow.localReady && gameAudioEnabled('sfx')) ensureAudioContext();
  if (lanRole === 'host') { flow.hostReady = flow.localReady; maybeStartOnlineMatchCountdown(); }
  else sendOnlineMatchSetup('ready', {ready: flow.localReady});
  syncRoyalUi(true);
}

function maybeStartOnlineMatchCountdown() {
  const flow = onlineMatchFlow;
  if (flow.phase === 'ready' && flow.peerHello && flow.peerInitialized && flow.hostReady && flow.guestReady) {
    flow.phase = 'countdown';
    paused = true;
    resumeCountdownEndAt = performance.now() + RESUME_COUNTDOWN_MS;
    lastResumeCountdownNumber = 0;
    clearHeldInput();
  }
  sendOnlineMatchStatus();
  sendLanState(true);
}

function privateMatchConfiguration() {
  return {selection: selectionPayload(), rules: matchRulePayload()};
}

function sendPrivateMatchConfiguration() {
  if (!onlineMatchFlow || lanRole !== 'host' || !onlineMatchFlow.privateRoom && !onlineMatchFlow.configured) return;
  sendOnlineMatchSetup('config', privateMatchConfiguration());
  sendLanState(true);
}

function receiveOnlineMatchSetup(message) {
  const flow = onlineMatchFlow;
  if (!flow || !lanConnected || !onlineSession || message.protocol !== 1 || message.match !== flow.id ||
      message.v !== LAN_SIGNAL_VERSION || message.room !== lanRoomCode || !lanRoomCode ||
      message.gameplay !== 'royal' || message.matchRules !== 'presets') return;
  if (message.kind === 'config' && lanRole === 'guest') {
    if (!['connected', 'ready'].includes(flow.phase) || !validSelectionState(message.selection) ||
        !validMatchRuleState(message.rules) || typeof message.rules.powerups !== 'boolean') return;
    if (!flow.privateRoom && (!flow.peerHello || flow.peerPowerups === null ||
        message.selection.arena !== onlineMatchAssignment.arena || message.rules.id !== onlineMatchAssignment.rules ||
        message.rules.powerups !== (flow.localPowerups && flow.peerPowerups))) { onlineSession.fail('incompatible'); return; }
    applySelectionState(message.selection);
    applyMatchRuleState(message.rules);
    flow.configuration = JSON.stringify({selection: message.selection, rules: message.rules});
    flow.configured = true;
    flow.agreedPowerups = message.rules.powerups;
    if (onlineHasState) sendOnlineMatchSetup('initialized', {configuration: flow.configuration});
  } else if (message.kind === 'initialized' && lanRole === 'host') {
    if (message.configuration !== JSON.stringify(privateMatchConfiguration())) return;
    flow.peerInitialized = true;
  } else if (message.kind === 'hello') {
    if (!flow.privateRoom) {
      if (message.powerupAgreement !== 1 || typeof message.powerupsPreference !== 'boolean' ||
          flow.peerPowerups !== null && flow.peerPowerups !== message.powerupsPreference) { onlineSession.fail('incompatible'); return; }
      flow.peerPowerups = message.powerupsPreference;
      if (lanRole === 'host' && !flow.configured) {
        flow.agreedPowerups = flow.localPowerups && flow.peerPowerups;
        if (matchPowerupsEnabled !== flow.agreedPowerups) { matchPowerupsEnabled = flow.agreedPowerups; matchRuleRevision++; resetRoyalRally(); }
        flow.configured = true;
      }
    }
    if (!flow.peerHello) {
      flow.peerHello = true;
      flow.connectedUntil = Math.max(flow.connectedUntil, performance.now() + 600);
      sendOnlineMatchHello();
    }
    if (lanRole === 'host') {
      sendPrivateMatchConfiguration();
      sendOnlineMatchStatus();
    }
  } else if (lanRole === 'host' && message.kind === 'ready' && (flow.phase === 'ready' || flow.phase === 'countdown' && message.ready === false) && flow.peerHello) {
    if (!flow.peerInitialized || message.ready !== undefined && typeof message.ready !== 'boolean') return;
    flow.guestReady = message.ready !== false;
    if (!flow.guestReady && flow.phase === 'countdown') {
      flow.phase = 'ready'; resumeCountdownEndAt = 0; lastResumeCountdownNumber = 0;
    }
    maybeStartOnlineMatchCountdown();
  } else if (lanRole === 'guest' && message.kind === 'status') {
    if (!Number.isSafeInteger(message.seq) || message.seq <= flow.remoteSequence ||
        typeof message.hostReady !== 'boolean' || typeof message.guestReady !== 'boolean' ||
        !['connected', 'ready', 'countdown', 'go'].includes(message.phase) ||
        !Number.isFinite(message.remainingMs) || message.remainingMs < 0 || message.remainingMs > RESUME_COUNTDOWN_MS) return;
    if (['countdown', 'go'].includes(message.phase) &&
        (!flow.localReady || !message.hostReady || !message.guestReady)) return;
    if (message.phase !== 'connected' && (!flow.configured || !onlineHasState)) return;
    const previousPhase = flow.phase;
    flow.remoteSequence = message.seq;
    flow.hostReady = message.hostReady;
    flow.guestReady = message.guestReady;
    flow.peerHello = true;
    flow.phase = message.phase;
    if (flow.phase === 'ready') {
      resumeCountdownEndAt = 0;
      lastResumeCountdownNumber = 0;
    }
    if (flow.phase === 'countdown') {
      paused = true;
      resumeCountdownEndAt = performance.now() + message.remainingMs;
    } else if (flow.phase === 'go') {
      // The host already plays the resume completion cue. A guest must hear it
      // from the authoritative GO status, never from an expired local timer.
      if (lanRole === 'guest' && previousPhase === 'countdown') beep(1040, 0.12, 0.065);
      lastResumeCountdownNumber = 0;
      // Only the host can release the guest, even if its local countdown expires.
      resumeCountdownEndAt = 0;
      onlineGameBlocked = false;
      flow.goUntil = performance.now() + 650;
    }
  }
  syncRoyalUi(true);
}

function tickOnlineMatchFlow() {
  const flow = onlineMatchFlow;
  if (!flow || flow.phase === 'playing') return;
  if (onlineSession?.secure && onlineSession.secure.phase !== 'active') return;
  const now = performance.now();
  if (flow.phase === 'go') {
    if (now >= flow.goUntil) { flow.phase = 'playing'; syncRoyalUi(true); }
    return;
  }
  if (flow.phase === 'failed' || flow.phase === 'connecting' || !lanConnected) return;
  if (!flow.peerHello || (lanRole === 'host' ? !flow.peerInitialized : flow.phase === 'connected')) {
    if (now >= flow.handshakeDeadline) { onlineSession?.fail('incompatible'); return; }
    if (now - flow.lastHelloAt >= 500) sendOnlineMatchHello();
  }
  if (lanRole === 'guest') {
    // The guest does not call updateResumeCountdown() because only the host
    // may release the match. Play its exact 3/2/1 cue on each local digit.
    if (flow.phase === 'countdown') {
      const number = Math.max(1, Math.ceil(resumeCountdownRemainingMs() / 1000));
      if (number !== lastResumeCountdownNumber) {
        lastResumeCountdownNumber = number;
        beep(number === 1 ? 720 : 600, 0.085, 0.06);
      }
    }
    return;
  }
  if (lanRole !== 'host') return;
  if (flow.phase === 'connected' && flow.peerHello && flow.peerInitialized && now >= flow.connectedUntil) {
    flow.phase = 'ready';
    sendOnlineMatchStatus();
    sendLanState(true);
    syncRoyalUi(true);
  } else if (flow.phase === 'countdown') {
    const previousNumber = lastResumeCountdownNumber;
    if (!updateResumeCountdown()) {
      flow.phase = 'go';
      flow.goUntil = now + 650;
      onlineGameBlocked = false;
      clearHeldInput();
      sendOnlineMatchStatus();
      serveOrContinue();
      sendLanState(true);
      return;
    }
    if (lastResumeCountdownNumber !== previousNumber) {
      sendOnlineMatchStatus();
      sendLanState(true);
    }
  }
  // Keep the existing 20 Hz host snapshots/countdown in sync without simulating
  // the ball, paddles, hazards, powerups or scores during setup.
  frame++;
  sendLanState(false);
}

function failOnlineMatchFlow(code) {
  closeOnlineConnection(false);
  onlineMatchFlow = {phase: 'failed', error: code === 'incompatible' ? ONLINE_ERRORS.incompatible :
    ['host_left', 'guest_left', 'opponent_left'].includes(code) ? ONLINE_ERRORS.opponent_left :
    'Could not connect. Try finding another match.'};
  onlineGameBlocked = paused = true;
  setMenusVisible(false);
  syncRoyalUi(true);
}

function leaveOnlineMatchFlow(retry = false) {
  startOnlineSetup();
  if (retry) findOnlineMatch();
}

function initOnlineMatchFlowUi() {
  const overlay = document.createElement('section');
  overlay.id = 'onlineMatchFlow';
  overlay.className = 'online-match-flow match-ui';
  overlay.hidden = true;
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('aria-labelledby', 'onlineFlowTitle');
  const card = document.createElement('div');
  card.className = 'online-flow-card';
  const title = document.createElement('h2');
  title.id = 'onlineFlowTitle';
  title.setAttribute('role', 'status');
  title.setAttribute('aria-live', 'polite');
  const note = document.createElement('p');
  note.id = 'onlineFlowNote';
  const configuration = document.createElement('p');
  configuration.id = 'onlineFlowConfiguration';
  const actions = document.createElement('div');
  actions.className = 'online-flow-actions';
  actions.append(royalButton('onlineReadyButton', "I'm ready", confirmOnlineMatchReady, 'match-primary'),
    royalButton('onlineRetryButton', 'Retry', () => leaveOnlineMatchFlow(true)),
    royalButton('onlineFlowBack', 'Back', () => leaveOnlineMatchFlow()));
  card.append(title, note, configuration, actions);
  overlay.append(card);
  document.body.append(overlay);
}

function syncOnlineMatchFlowUi() {
  const panel = byId('onlineMatchFlow');
  if (!panel) return;
  panel.hidden = !onlineMatchFlowVisible() || document.body.classList.contains('title-active');
  if (panel.hidden) return;
  const flow = onlineMatchFlow;
  const previousPhase = panel.dataset.phase;
  panel.dataset.phase = flow.phase;
  const countdown = flow.phase === 'countdown';
  const go = flow.phase === 'go';
  panel.setAttribute('role', go ? 'status' : 'dialog');
  if (go) panel.removeAttribute('aria-modal');
  else panel.setAttribute('aria-modal', 'true');
  royalText(byId('onlineFlowTitle'), countdown ? String(Math.max(1, Math.ceil(resumeCountdownRemainingMs() / 1000))) :
    go ? 'GO!' : flow.phase === 'failed' ? 'Connection failed' : flow.phase === 'ready' ? 'ARE YOU READY?' :
    flow.phase === 'connected' ? 'CONNECTED' : 'CONNECTING...');
  royalText(byId('onlineFlowNote'), countdown || go ? '' : flow.phase === 'failed' ? flow.error :
    flow.phase === 'ready' ? flow.localReady ? 'Waiting for your opponent to be ready.' :
      flow.hostReady || flow.guestReady ? 'Your opponent is ready. Confirm when you are ready.' :
      'Both players must confirm before the countdown.' : flow.privateRoom ? '' : 'Classic Match · First to 10');
  byId('onlineReadyButton').hidden = flow.phase !== 'ready';
  byId('onlineReadyButton').disabled = Boolean(flow.localReady && !flow.privateRoom);
  royalText(byId('onlineFlowConfiguration'), (flow.privateRoom || flow.configured) && flow.phase !== 'failed' ?
    localizeText(currentLevel().name) + ' · ' + localizeText(matchRule().label) + ' · ' +
    localizeText(matchPowerupsEnabled ? 'Royal Powerups: On' : 'Royal Powerups: Off') : '');
  royalText(byId('onlineReadyButton'), flow.localReady ? flow.privateRoom ? 'Ready — Undo' : 'Ready!' : "I'm ready");
  byId('onlineRetryButton').hidden = flow.phase !== 'failed';
  byId('onlineFlowBack').hidden = go;
  royalText(byId('onlineFlowBack'), flow.phase === 'failed' ? 'Back' : 'Cancel');
  // Focus the explicit confirmation as it appears; never interpret a held key as ready.
  if (previousPhase !== flow.phase && flow.phase === 'ready') byId('onlineReadyButton').focus({preventScroll: true});
}

// Session-local agreement on the reliable, already authenticated control channel.
// A new round is prepared by the host, acknowledged by the consenting guest,
// then reset exactly once by the host. Snapshot/input round tags fence old packets.
function multiplayerRematch() {
  if (!onlineSession || !['host', 'guest'].includes(lanRole)) return null;
  if (!onlineSession.rematch) {
    onlineSession.rematch = {round: 0, local: false, remote: false, phase: 'playing',
      token: lanRole === 'host' ? Array.from(crypto.getRandomValues(new Uint32Array(4)),
        n => n.toString(16).padStart(8, '0')).join('') : null, lastSend: -Infinity};
  }
  return onlineSession.rematch;
}

function receiveRematchHello(message) {
  const state = multiplayerRematch();
  if (!state || message.rematch !== 1 || !/^[a-f0-9]{32}$/.test(message.rematchToken || '')) return;
  if (lanRole === 'guest' && state.token === null) state.token = message.rematchToken;
  if (state.token === message.rematchToken) onlineRematchReady = true;
}

function multiplayerRematchVisible() {
  return Boolean(mode === 2 && gameOver && onlineSession && lanConnected);
}

function sendRematch(kind, round = multiplayerRematch()?.round) {
  const state = multiplayerRematch();
  if (!state || !onlineRematchReady || !lanConnected) return false;
  state.lastSend = performance.now();
  return lanSend({v: LAN_SIGNAL_VERSION, room: lanRoomCode, type: 'rematch', protocol: 1,
    token: state.token, round, kind});
}

function requestMultiplayerRematch() {
  const state = multiplayerRematch();
  if (!multiplayerRematchVisible() || !onlineRematchReady || onlineGameBlocked || !state || state.local) return;
  state.local = true;
  sendRematch('accept');
  prepareMultiplayerRematch();
  syncRoyalUi(true);
}

function prepareMultiplayerRematch() {
  const state = multiplayerRematch();
  if (lanRole !== 'host' || !state || !gameOver || !state.local || !state.remote ||
      state.phase === 'starting' || state.round >= Number.MAX_SAFE_INTEGER - 1) return;
  state.phase = 'starting';
  state.activeWait = 0;
  state.at = performance.now();
  sendRematch('start');
}

function receiveMultiplayerRematch(message) {
  const state = multiplayerRematch();
  if (!state || !onlineRematchReady || !lanConnected || message.v !== LAN_SIGNAL_VERSION ||
      message.room !== lanRoomCode || !lanRoomCode || message.gameplay !== 'royal' ||
      message.matchRules !== 'presets' || message.protocol !== 1 || message.token !== state.token ||
      !Number.isSafeInteger(message.round) || message.round < 0) return;
  if (message.kind === 'leave' && (message.round === state.round ||
      state.phase === 'awaiting-state' && message.round === state.round - 1 ||
      state.phase === 'starting' && message.round === state.round + 1)) {
    return endMultiplayerSession('Opponent left the match.');
  }
  if (lanRole === 'guest' && message.kind === 'start') {
    if (state.phase === 'awaiting-state' && message.round === state.round - 1) {
      sendRematch('started'); // Lost acknowledgement during transport recovery.
      return;
    }
    if (message.round !== state.round || !state.local || !gameOver || state.phase !== 'playing') return;
    state.round++;
    state.phase = 'awaiting-state';
    state.activeWait = 0;
    state.at = performance.now();
    onlineInputs.clear();
    onlineHasState = false;
    onlineLastInput = null;
    resetVisualHistory();
    sendRematch('started');
  } else if (lanRole === 'host' && message.kind === 'started') {
    if (state.phase !== 'starting' || message.round !== state.round + 1 || !state.local || !state.remote || !gameOver) return;
    state.round++;
    state.phase = 'playing'; // Commit before calling reset/UI hooks; duplicates cannot reenter.
    state.local = state.remote = false;
    lanRemoteInput = {axis: 0, targetY: null, lastAt: 0};
    onlineInputs.clear();
    onlineLastInput = null;
    clearHeldInput();
    shakeFrames = 0;
    resumeCountdownEndAt = 0;
    lastResumeCountdownNumber = 0;
    if (onlineMatchFlow) onlineMatchFlow.phase = 'playing';
    startLevel(); // Existing score, hazard, paddle, ball, powerup and countdown reset.
    if (typeof hideFirstStartControls === 'function') hideFirstStartControls();
    setMenusVisible(false);
    beginPointServeCountdown();
    sendLanState(true);
  } else if (message.kind === 'accept' && message.round === state.round && gameOver) {
    state.remote = true;
    prepareMultiplayerRematch();
  }
  syncRoyalUi(true);
}

function acceptMultiplayerRound(message) {
  const state = multiplayerRematch();
  return !onlineRematchReady || !['input', 'state', 'action'].includes(message?.type) ||
    state && (message.round === state.round || state.round === 0 && message.round === undefined) &&
    !(lanRole === 'host' && state.phase === 'starting');
}

function tickMultiplayerRematch() {
  const state = onlineSession?.rematch;
  if (!state || !onlineRematchReady || !lanConnected) return;
  const now = performance.now();
  const blocked = onlineGameBlocked || onlineSession.secure && onlineSession.secure.phase !== 'active';
  if (state.phase === 'starting' || state.phase === 'awaiting-state') {
    if (!blocked) state.activeWait += Math.max(0, now - (state.at ?? now));
    state.at = now;
    if (state.activeWait > 12000) { endMultiplayerSession(ONLINE_ERRORS.connection_lost); return; }
  }
  if (blocked || now - state.lastSend < 500) return;
  if (state.phase === 'starting') sendRematch('start');
  else if (state.phase === 'awaiting-state') sendRematch('started');
  else if (gameOver && state.local) sendRematch('accept');
}

function finishMultiplayerRematchSnapshot() {
  const state = onlineSession?.rematch;
  if (state?.phase === 'awaiting-state' && !gameOver) {
    state.phase = 'playing';
    state.local = state.remote = false;
    clearHeldInput();
    syncRoyalUi(true);
  }
}

// The terminal dialog owns only local UI state. Detach the session before any
// async close completes, so late callbacks cannot revive it or navigate away.
let multiplayerDisconnect = null;

function endMultiplayerSession(message = 'Opponent disconnected.') {
  if (multiplayerDisconnect || !onlineSession) return;
  const ended = multiplayerDisconnect = {origin: onlineSession.multiplayerOrigin ||
    (onlineManualLanSelected ? 'lan' : 'private'), role: lanRole, ready: false};
  onlineGameBlocked = paused = true;
  clearHeldInput();
  const closed = closeOnlineConnection(false);
  onlineGameBlocked = paused = true;
  setMenusVisible(false);
  byId('classicLanDialog').hidden = true;
  setLanStatus(message);
  // Native LAN acknowledges socket/discovery shutdown; WebSockets must finish
  // closing (including already queued frames) before the local popup appears.
  Promise.resolve(closed).then(() => {
    if (multiplayerDisconnect !== ended) return;
    ended.ready = true;
    byId('multiplayerDisconnected').hidden = false;
    syncRoyalUi(true);
    byId('multiplayerReturn').focus({preventScroll: true});
  });
}

function acknowledgeMultiplayerDisconnect() {
  if (!multiplayerDisconnect?.ready) return;
  const {origin} = multiplayerDisconnect;
  multiplayerDisconnect = null;
  byId('multiplayerDisconnected').hidden = true;
  resetFrameClock();
  // Returning is local navigation, not consent to reopen the queue socket.
  if (origin === 'lan') openOfflineLanSetup(false);
  else {
    startOnlineSetup(false, false, false);
    if (origin === 'private') byId('onlinePrivateRooms').open = true;
  }
  onlineGameBlocked = paused = true;
  syncRoyalUi(true);
}

function leaveMultiplayerSession(message = '', notify = true) {
  const origin = onlineSession?.multiplayerOrigin || (onlineManualLanSelected ? 'lan' : 'private');
  if (notify) sendRematch('leave');
  // Closing signaling also supplies a departure notification if the final
  // encrypted control packet was still queued when the connection closed.
  if (origin === 'lan') openOfflineLanSetup(false);
  else {
    startOnlineSetup(false);
    if (origin === 'private') byId('onlinePrivateRooms').open = true;
  }
  onlineGameBlocked = paused = true;
  setLanStatus(message || 'Find an opponent or create/join a private room.');
  syncRoyalUi(true);
}

function initMultiplayerRematchUi() {
  const panel = document.createElement('section');
  panel.id = 'multiplayerResult';
  panel.className = 'online-match-flow match-ui';
  panel.hidden = true;
  panel.setAttribute('role', 'dialog');
  panel.setAttribute('aria-modal', 'true');
  panel.setAttribute('aria-labelledby', 'multiplayerResultTitle');
  const card = document.createElement('div'); card.className = 'online-flow-card';
  const title = document.createElement('h2'); title.id = 'multiplayerResultTitle';
  const score = document.createElement('p'); score.id = 'multiplayerResultScore';
  const note = document.createElement('p'); note.id = 'multiplayerResultNote';
  note.setAttribute('role', 'status'); note.setAttribute('aria-live', 'polite');
  const actions = document.createElement('div'); actions.className = 'online-flow-actions';
  actions.append(royalButton('multiplayerRematch', 'Rematch', requestMultiplayerRematch, 'match-primary'),
    royalButton('multiplayerBack', 'Back', () => leaveMultiplayerSession()));
  card.append(title, score, actions, note); panel.append(card); document.body.append(panel);
}

function syncMultiplayerRematchUi() {
  const panel = byId('multiplayerResult');
  if (!panel) return;
  panel.hidden = !multiplayerRematchVisible() || document.body.classList.contains('title-active');
  if (panel.hidden) return;
  const state = multiplayerRematch(), inverted = lanRole === 'guest';
  royalText(byId('multiplayerResultTitle'), multiplayerVictoryText());
  byId('multiplayerResultScore').textContent = inverted ? right.score + ' – ' + left.score : left.score + ' – ' + right.score;
  byId('multiplayerRematch').disabled = !onlineRematchReady || state.local || onlineGameBlocked;
  royalText(byId('multiplayerResultNote'), !onlineRematchReady ? 'Both players must reload the latest game.' :
    state.local ? 'Waiting for opponent...' : state.remote ? 'Your opponent wants a rematch.' : '');
}

// Peer availability belongs to the authenticated session, never to paddle input.
// Background timers may stop entirely. The visible peer owns the deadline too,
// and every return checks wall-clock time before accepting more gameplay.
const MULTIPLAYER_PRESENCE = Object.freeze({probe: 2000, stale: 8000, grace: 30000, poll: 500});

function multiplayerPresence() { return onlineSession?.presence; }
function multiplayerSuspended() { return Boolean(multiplayerPresence()?.suspended); }

function stopMultiplayerPresence(session) {
  if (session?.presence) clearInterval(session.presence.timer);
  if (session) session.presence = null;
  if (onlineSession && session !== onlineSession) return;
  const panel = document.getElementById('multiplayerUnavailable');
  if (panel) panel.hidden = true;
}

function receivePresenceHello(message) {
  if (message.presence !== 1 || !onlineRematchReady || multiplayerPresence()) return;
  const now = Date.now(), session = onlineSession;
  const p = session.presence = {epoch: 0, phase: 'playing', suspended: false,
    localActive: true, remoteActive: true, revision: 0, remoteRevision: -1,
    lastHeard: now, lastSent: now, probe: 0, awaitingProbe: 0, transportDown: false};
  p.timer = setInterval(() => { if (onlineSession === session) tickMultiplayerPresence(); }, MULTIPLAYER_PRESENCE.poll);
  if (document.hidden || window.KingPongBackgrounded) setMultiplayerAvailability(false);
}

function sendMultiplayerPresence(kind, fields = {}) {
  const p = multiplayerPresence();
  if (!p || !lanConnected) return false;
  return lanSend({v: LAN_SIGNAL_VERSION, room: lanRoomCode, type: 'presence', protocol: 1,
    token: multiplayerRematch().token, epoch: p.epoch, kind,
    revision: p.revision, active: p.localActive, ...fields});
}

function showMultiplayerUnavailable() {
  let panel = document.getElementById('multiplayerUnavailable');
  if (!panel) {
    panel = document.createElement('p');
    panel.id = 'multiplayerUnavailable'; panel.className = 'multiplayer-status';
    panel.setAttribute('role', 'status'); panel.setAttribute('aria-live', 'polite');
    setLocalizedText(panel, 'Opponent unavailable — Game paused.');
    document.getElementById('matchBar').append(panel);
  }
  panel.hidden = !multiplayerSuspended();
}

function suspendMultiplayerPresence(reason = 'peer-hold') {
  const p = multiplayerPresence();
  if (!p) return;
  if (p.suspended) {
    if (p.phase !== 'held') {
      p.phase = 'held';
      if (lanRole === 'host') { p.epoch++; sendMultiplayerPresence('hold'); }
    }
    return;
  }
  p.suspended = true; p.since = Date.now(); p.flowAt = performance.now();
  p.reason = reason;
  p.wasPaused = paused; p.countdown = resumeCountdownRemainingMs();
  p.phase = 'held';
  if (lanRole === 'host') p.epoch++;
  onlineGameBlocked = paused = true;
  suspendPointServeCountdown(); resumeCountdownEndAt = 0; lastResumeCountdownNumber = 0;
  clearHeldInput(); onlineInputs.clear(); onlineLastInput = null; resetVisualHistory();
  resetFrameClock();
  showMultiplayerUnavailable();
  if (lanRole === 'host') sendMultiplayerPresence('hold');
}

function presenceExpired(p = multiplayerPresence()) {
  if (!p?.suspended || Date.now() - p.since < MULTIPLAYER_PRESENCE.grace) return false;
  endMultiplayerSession();
  return true;
}

function setMultiplayerAvailability(active) {
  const p = multiplayerPresence();
  if (!p || presenceExpired(p)) return;
  active = Boolean(active);
  if (p.localActive === active) return;
  p.localActive = active; p.revision++;
  if (!active) suspendMultiplayerPresence('local-background');
  sendMultiplayerPresence('status');
  maybeResumeMultiplayer();
}

function multiplayerTransportInterrupted(reason = 'transport-recovery') {
  const p = multiplayerPresence();
  if (!p) return false;
  p.transportDown = true;
  suspendMultiplayerPresence(reason);
  return true;
}

function multiplayerTransportResumed() {
  const p = multiplayerPresence();
  if (!p) return false;
  if (presenceExpired(p)) return true;
  p.transportDown = false;
  sendMultiplayerPresence('status');
  maybeResumeMultiplayer();
  return true;
}

function noteMultiplayerTraffic() {
  const p = multiplayerPresence();
  if (!p || presenceExpired(p)) return;
  p.lastHeard = Date.now();
  maybeResumeMultiplayer();
}

function maybeResumeMultiplayer() {
  const p = multiplayerPresence();
  if (!p || !p.suspended || presenceExpired(p) || lanRole !== 'host' ||
      p.phase !== 'held' || !p.localActive || !p.remoteActive || p.transportDown ||
      Date.now() - p.lastHeard >= MULTIPLAYER_PRESENCE.stale) return;
  p.phase = 'offered';
  sendMultiplayerPresence('offer');
}

function commitMultiplayerResume() {
  const p = multiplayerPresence();
  if (!p || !p.suspended || presenceExpired(p)) return;
  // The snapshot handshake proves the peer is back. A transport ACK for an
  // older control can still be in flight; do not charge its suspended time
  // against the normal 12-second delivery deadline after committing recovery.
  for (const control of onlineSession.secure?.pending?.values() || []) control.created = Date.now();
  p.suspended = false; p.phase = 'playing'; p.awaitingProbe = 0; p.reason = 'snapshot-committed';
  const elapsed = performance.now() - p.flowAt;
  if (onlineMatchFlow) for (const key of ['handshakeDeadline', 'connectedUntil', 'goUntil'])
    if (Number.isFinite(onlineMatchFlow[key])) onlineMatchFlow[key] += elapsed;
  onlineGameBlocked = onlineMatchFlowBlocksPlay();
  clearHeldInput(); onlineInputs.clear(); onlineLastInput = null; resetVisualHistory(); resetFrameClock();
  if (lanRole === 'host') {
    // Preserve manual pause, results and ready consent. An interrupted rally or
    // countdown always resumes through the existing countdown/audio machinery.
    const countdown = onlineMatchFlow?.phase === 'countdown' || p.countdown > 0 ||
      !p.wasPaused && !waitingForServe && !gameOver;
    paused = p.wasPaused || countdown || onlineGameBlocked;
    if (countdown) { resumeCountdownEndAt = performance.now() + RESUME_COUNTDOWN_MS; lastResumeCountdownNumber = 0; }
    sendMultiplayerPresence('resume');
    p.sendingSnapshot = true; sendLanState(true); p.sendingSnapshot = false;
  }
  showMultiplayerUnavailable(); syncRoyalUi(true);
}

function receiveMultiplayerPresence(m) {
  const p = multiplayerPresence();
  if (!p || !lanConnected || m.v !== LAN_SIGNAL_VERSION || m.room !== lanRoomCode ||
      m.gameplay !== 'royal' || m.matchRules !== 'presets' || m.protocol !== 1 ||
      m.token !== multiplayerRematch().token || !Number.isSafeInteger(m.epoch) || m.epoch < 0 ||
      !Number.isSafeInteger(m.revision) || m.revision < 0 || typeof m.active !== 'boolean' ||
      !['status', 'status-ack', 'ping', 'pong', 'hold', 'offer', 'ready', 'snapshot-ack', 'resume', 'leave'].includes(m.kind)) return;
  if (m.kind === 'leave') { endMultiplayerSession(); return; }
  if (presenceExpired(p)) return;
  if (m.revision < p.remoteRevision) return;
  p.remoteRevision = m.revision; p.remoteActive = m.active; p.lastHeard = Date.now();
  if (!m.active) suspendMultiplayerPresence('peer-background');
  if (m.kind === 'status') sendMultiplayerPresence('status-ack');
  if (m.kind === 'ping' && Number.isSafeInteger(m.probe) && m.probe > 0)
    sendMultiplayerPresence('pong', {probe: m.probe});
  if (m.kind === 'pong' && m.probe === p.awaitingProbe) p.awaitingProbe = 0;
  if (lanRole === 'guest' && (m.kind === 'hold' || m.kind === 'offer') && m.epoch >= p.epoch) {
    if (m.epoch === p.epoch && !p.suspended) return; // Delayed message from a completed recovery.
    if (m.epoch === p.epoch && p.phase !== 'held') {
      if (m.kind === 'offer') sendMultiplayerPresence(p.phase === 'acknowledged' ? 'snapshot-ack' : 'ready');
      return; // A duplicate hold/offer cannot roll back an in-flight handshake.
    }
    suspendMultiplayerPresence('peer-hold');
    p.epoch = m.epoch;
    if (m.kind === 'offer' && p.localActive && m.active && !p.transportDown) {
      p.phase = 'snapshot'; sendMultiplayerPresence('ready');
    }
  } else if (lanRole === 'host' && m.epoch === p.epoch && p.localActive && p.remoteActive && !p.transportDown) {
    if (m.kind === 'ready' && ['offered', 'snapshot'].includes(p.phase)) {
      p.phase = 'snapshot'; p.sendingSnapshot = true; sendLanState(true); p.sendingSnapshot = false;
    } else if (m.kind === 'snapshot-ack' && p.phase === 'snapshot') commitMultiplayerResume();
  } else if (lanRole === 'guest' && m.kind === 'resume' && m.epoch === p.epoch &&
      p.phase === 'acknowledged' && p.localActive && p.remoteActive && !p.transportDown) commitMultiplayerResume();
  maybeResumeMultiplayer();
}

function acceptMultiplayerPresence(m) {
  if (!m || typeof m !== 'object') return false;
  const p = multiplayerPresence();
  if (!p) return true;
  if (presenceExpired(p)) return false;
  if (['state', 'input', 'action', 'match-setup'].includes(m.type) && m.presenceEpoch !== p.epoch &&
      !(p.epoch === 0 && m.presenceEpoch === undefined)) return false;
  if (!p.suspended) return true;
  return m.type === 'state' && lanRole === 'guest' && p.phase === 'snapshot' && m.presenceSnapshot === true ||
    m.type === 'rematch' && m.kind === 'leave';
}

function finishPresenceSnapshot(m) {
  const p = multiplayerPresence();
  if (p?.suspended && p.phase === 'snapshot' && m.presenceSnapshot === true && m.presenceEpoch === p.epoch) {
    p.phase = 'acknowledged'; sendMultiplayerPresence('snapshot-ack');
  }
}

function tickMultiplayerPresence() {
  const p = multiplayerPresence();
  if (!p || presenceExpired(p)) return;
  const now = Date.now();
  if (now - p.lastHeard >= MULTIPLAYER_PRESENCE.stale) {
    suspendMultiplayerPresence('traffic-timeout');
    // Reuse the existing ICE restart -> TURN -> encrypted WebSocket recovery.
    // An explicitly backgrounded peer may simply have suspended its JS timers.
    if (p.remoteActive && p.localActive && !p.transportDown && onlineSession.secure?.mode === 'rtc')
      onlineSession.secure.rtcFailed();
  }
  if (!p.localActive) return;
  if (!p.awaitingProbe && now - p.lastHeard >= MULTIPLAYER_PRESENCE.probe && now - p.lastSent >= MULTIPLAYER_PRESENCE.probe) {
    p.awaitingProbe = ++p.probe;
    if (!sendMultiplayerPresence('ping', {probe: p.awaitingProbe})) p.awaitingProbe = 0;
  }
}

function multiplayerRecoveryRemaining(session) {
  const p = session?.presence;
  return p?.suspended ? Math.max(0, MULTIPLAYER_PRESENCE.grace - (Date.now() - p.since)) : 0;
}

function multiplayerPageHide(event) {
  if (event.persisted) { setMultiplayerAvailability(false); return; }
  stopMatchmaking();
  if (onlineSession) {
    sendMultiplayerPresence('leave'); sendRematch('leave');
    onlineSession.close(); // Best effort; watchdog also covers process kills without any event.
  }
}

window.addEventListener('pagehide', multiplayerPageHide);
function refreshMultiplayerAvailability() {
  const active = !document.hidden && !window.KingPongBackgrounded;
  // hasFocus() can lag visibilitychange/pageshow. A visible return must also
  // release the legacy input gate, even if no separate focus event follows.
  if (active && multiplayerPresence()) gameWindowFocused = true;
  setMultiplayerAvailability(active);
}
window.addEventListener('pageshow', refreshMultiplayerAvailability);
document.addEventListener('visibilitychange', refreshMultiplayerAvailability);
document.addEventListener('kingpong-background', refreshMultiplayerAvailability);

// Focus and visibility must suspend through the same protocol. The legacy
// blur pause has no matching resume and used to leave an active peer frozen
// when a browser omitted/reordered visibility events. Presence takes ownership
// before that handler can turn automatic suspension into a manual Pause.
function recordMultiplayerFocusLoss() {
  setMultiplayerAvailability(false);
}
function recordMultiplayerFocusReturn() {
  refreshMultiplayerAvailability();
}

// Native LAN functions remain intact. Route only online sessions through the
// existing browser transport and prediction adapters, after legacy declarations.
function installOnlineSupport() {
  onlineNativeTransport = typeof lanLocalSignal !== 'undefined';
  const nativeClose = onlineNativeTransport ? closeLanConnection : null;
  const nativeSetup = onlineNativeTransport ? startLanTwoPlayerSetup : null;
  const nativeHost = onlineNativeTransport ? hostLanMatch : null;
  const nativeJoin = onlineNativeTransport ? prepareLanJoin : null;
  window.closeLanConnection = (show = true, keepQueue = false) => {
    if (nativeClose && !onlineSession && !onlineTransportSelected) nativeClose(false);
    closeOnlineConnection(show, keepQueue);
  };
  window.startLanTwoPlayerSetup = fromTitle => {
    if (!nativeSetup) return startOnlineSetup(fromTitle);
    closeLanConnection(false);
    onlineTransportSelected = false;
    nativeSetup(fromTitle);
  };
  window.hostLanMatch = () => onlineTransportSelected || !nativeHost ? hostOnlineMatch() : nativeHost();
  window.prepareLanJoin = () => onlineTransportSelected || !nativeJoin ? prepareOnlineJoin() : nativeJoin();
  if (!onlineNativeTransport) window.sanitizeRoomCode = sanitizeOnlineRoomCode;
  for (const [name, online] of Object.entries({lanSend: onlineLanSend, sendLanInput: onlineSendLanInput,
      sendLanState: onlineSendLanState, applyLanHostState: onlineApplyLanHostState, updatePlayerPaddles: onlineUpdatePlayerPaddles})) {
    const local = window[name];
    window[name] = (...args) => onlineSession ? online(...args) : local(...args);
  }
  for (const name of ['update', 'requestServeOrContinue', 'requestTogglePause', 'requestRetryLevel']) {
    const original = window[name];
    window[name] = (...args) => {
      if (multiplayerDisconnect || name !== 'update' && royalInputModal()) return;
      if (name === 'update') {
        tickMultiplayerPresence();
        if (!multiplayerSuspended()) { tickOnlineMatchFlow(); tickMultiplayerRematch(); }
      }
      if (multiplayerSuspended()) return;
      if (name === 'requestServeOrContinue' && multiplayerRematchVisible()) return;
      if (name === 'requestRetryLevel' && mode === 2 && onlineSession && (gameOver || lanRole === 'guest')) return;
      if (name === 'requestServeOrContinue' && onlineMatchFlowBlocksPlay()) return;
      if (mode === 2 && onlineGameBlocked) { suspendPointServeCountdown(); return; }
      return original(...args);
    };
  }
  for (const name of ['serveOrContinue', 'togglePause', 'retryLevel', 'pointForPlayer', 'pointForCpu']) {
    const original = window[name];
    window[name] = (...args) => {
      if (mode === 2 && onlineSession && (name === 'retryLevel' && (gameOver || lanRole === 'guest') ||
          name === 'serveOrContinue' && gameOver)) return;
      if (multiplayerDisconnect || onlineMatchFlowBlocksPlay() || multiplayerSuspended()) return;
      return original(...args);
    };
  }
  const receive = handleLanMessage;
  window.handleLanMessage = raw => {
    if (multiplayerDisconnect) return;
    if (typeof raw !== 'string' || raw.length > 8192) return;
    let message;
    try { message = JSON.parse(raw); } catch { return; }
    if (onlineSession && Array.isArray(message)) {
      message = decodeOnlineWire(message);
      if (!message) return;
      raw = JSON.stringify(message);
    }
    if (onlineSession && message?.type === 'net-format') { receiveOnlineWireHello(message); return; }
    if (message?.type === 'presence') { receiveMultiplayerPresence(message); return; }
    if (!acceptMultiplayerPresence(message)) return;
    if (message?.type === 'rematch') { receiveMultiplayerRematch(message); return; }
    if (onlineSession && !acceptMultiplayerRound(message)) return;
    // A remote legacy Retry action is not consent from the host. The host's
    // existing mid-match Restart control remains available locally.
    if (onlineSession && message?.type === 'action' && message.action === 'retry') return;
    if (message?.type === 'match-setup') { receiveOnlineMatchSetup(message); return; }
    if (onlineMatchFlowBlocksPlay() && message?.type === 'action') return;
    const needsState = onlineMatchFlow?.configured && !onlineHasState;
    receive(raw);
    if (message?.type === 'state' && message.seq === lanLastStateSeq) {
      finishPresenceSnapshot(message); finishMultiplayerRematchSnapshot(); noteMultiplayerTraffic();
    } else if (message?.type === 'input' && message.seq === lanLastInputSeq) noteMultiplayerTraffic();
    // Acknowledge the first accepted snapshot immediately; no extra retry delay.
    if (needsState && onlineHasState && lanRole === 'guest' && onlineMatchFlow)
      sendOnlineMatchSetup('initialized', {configuration: onlineMatchFlow.configuration});
  };
  const levelChoice = applyCustomLevelPickerChoice;
  window.applyCustomLevelPickerChoice = value => { if (!matchmakingLocked()) levelChoice(value); };
  const guestMessage = handleLanGuestMessage;
  window.handleLanGuestMessage = message => {
    if (validMatchmakingState(message)) guestMessage(message);
  };
}
